INSERT INTO public.reference_entries (category_id, group_label, entry_data, note, order_index) VALUES (cat_waktu_id, 'note_irregular', '{"note":"Pola tidak beraturan penting: 4 jam=よじかん (bukan よんじかん), 1 hari=いちにち tapi 2 hari=ふつか (bukan にじつ — pola khusus 1-10 hari beda dari pola angka biasa), 6 bulan=ろっかげつ atau はんとし (setengah tahun), 4 tahun=よねん (bukan よんねん)."}'::jsonb, 'Pola tidak beraturan penting: 4 jam=よじかん (bukan よんじかん), 1 hari=いちにち tapi 2 hari=ふつか (bukan にじつ — pola khusus 1-10 hari beda dari pola angka biasa), 6 bulan=ろっかげつ atau はんとし (setengah tahun), 4 tahun=よねん (bukan よんねん).', 103);
